<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {login} from '../api/http';const router=useRouter(),username=ref('admin'),password=ref('admin123'),submitting=ref(false),errorMessage=ref('');async function submit(){errorMessage.value='';submitting.value=true;try{if(import.meta.env.VITE_DEMO_MODE==='true')localStorage.setItem('zhuatech_bpm_token','demo-mode');else await login(username.value,password.value);await router.push('/admin/cockpit')}catch(e){errorMessage.value=e.response?.data?.message||'登录失败，请检查账号、密码和后端服务'}finally{submitting.value=false}}</script>
<template><div class="login-page"><section class="login-story"><div class="login-brand"><span>ZH</span><div><b>ZhuaTech BPM</b><small>知华科技业务流程管理系统</small></div></div><div class="story-copy"><p>PROCESS, CLEARLY ORCHESTRATED</p><h1>让每一项业务，<br/>沿着规则高效流转。</h1><span>连接流程、表单、规则和任务，让跨部门协作有时效、有边界、可追溯。</span></div><div class="story-metric"><div><b>42 个</b><span>已发布流程</span></div><div><b>92.4%</b><span>SLA 达标率</span></div><div><b>63.4%</b><span>SLA 目标执行</span></div></div><footer>上海如静知华信息科技有限公司 · www.zhuatech.cn</footer></section><form @submit.prevent="submit"><p>安全登录</p><h2>进入流程运营中心</h2><label>账号<input v-model="username" autocomplete="username"/></label><label>密码<input v-model="password" type="password" autocomplete="current-password"/></label><div class="form-meta"><span>☑ 保持登录</span><a>无法登录？</a></div><p v-if="errorMessage" class="login-error">{{errorMessage}}</p><button class="button primary" :disabled="submitting">{{submitting?'正在验证…':'登录系统'}}</button><small>演示账号：admin / admin123</small></form></div></template>
